<template><div class="setup-grid"><template v-for="field in fields.filter(f=>!f.when||f.when(modelValue))" :key="field.key"><label v-if="field.type==='checkbox'" class="setup-check" :class="{'setup-wide':field.wide}"><input type="checkbox" :checked="!!modelValue[field.key]" :disabled="disabled" @change="update(field,$event.target.checked)" />{{ field.label }}</label><label v-else class="setup-label" :class="{'setup-wide':field.type==='textarea'||field.wide}">{{ field.label }}<small>{{ field.required?'مطلوب':'اختياري' }}</small><textarea v-if="field.type==='textarea'" class="setup-input" :value="modelValue[field.key]" :required="field.required" :disabled="disabled" :rows="field.rows||3" @input="update(field,$event.target.value)" /><select v-else-if="field.type==='select'" class="setup-input" :value="modelValue[field.key]??''" :required="field.required" :disabled="disabled" @change="select(field,$event.target.value)"><option value="">اختر</option><option v-for="option in options(field)" :key="option.value" :value="option.value">{{ option.title }}</option></select><input v-else class="setup-input" :type="field.type||'text'" :value="modelValue[field.key]??''" :required="field.required" :disabled="disabled" :min="field.min" :max="field.max" :step="field.step||'any'" :maxlength="field.type==='password'?undefined:1000" :autocomplete="field.type==='password'?'new-password':undefined" @input="update(field,field.type==='number'?($event.target.value===''?null:Number($event.target.value)):$event.target.value)" /><small v-if="field.help">{{ field.help }}</small></label></template></div></template>
<script setup>
const props=defineProps({modelValue:{type:Object,required:true},fields:{type:Array,default:()=>[]},sources:{type:Object,default:()=>({})},disabled:Boolean})
const emit=defineEmits(['update:modelValue'])
const update=(field,value)=>emit('update:modelValue',{...props.modelValue,[field.key]:value})
function options(field){let rows=field.items||props.sources[field.source]||[];if(field.groupFilter)rows=rows.filter(r=>Number(r.unit_group_id)===Number(props.modelValue.unit_group_id));return rows.map(r=>({value:r.value??r.id,title:r.title??r.name??r.label??r.id}))}
function select(field,value){const found=options(field).find(r=>String(r.value)===value);update(field,found?found.value:null)}
</script>
